// 24-S3 acceptance: refused edits explained, with the input kept
// (`notice.ts`). Do not edit this file to match an implementation.
import { describe, expect, it } from 'vitest';
import { createGrid, withLetter, type Grid } from '@/engine/grid';
import { enterHintsPhase } from '@/engine/phase';
import { serializeGrid } from '@/lib/puzzle-storage';
import { publishRefusalMessage, refusalNotice } from './notice';
import type { Operation, OperationBody } from './operation';

function letters(grid: Grid, entries: Array<[number, number, string]>): Grid {
  return entries.reduce((next, [col, row, letter]) => withLetter(next, { col, row }, letter), grid);
}
// MAGIC down from the top-right of a 5×5, ABRAHAM-like row across the top.
const grid = letters(createGrid({ cols: 5, rows: 5 }), [
  [0, 0, 'M'], [1, 0, 'A'], [2, 0, 'S'], [3, 0, 'K'], [4, 0, 'S'],
  [4, 1, 'A'], [4, 2, 'G'], [4, 3, 'I'], [4, 4, 'C'],
]);
const op = (body: OperationBody): Operation => ({ opId: 'o', puzzleId: 'p', clientId: 't', epoch: 0, baseVersion: 0, ...body } as Operation);
const down = op({ kind: 'cells', writes: [{ col: 4, row: 1, value: 'A' }, { col: 4, row: 2, value: 'G' }, { col: 4, row: 3, value: 'I' }, { col: 4, row: 4, value: 'C' }] });

describe('24-S3-9 refusal notices', () => {
  it('names the entry and keeps the word as the builder saw it', () => {
    const notice = refusalNotice(down, 'locked', serializeGrid(grid), 'grid');
    expect(notice).toEqual({ message: "Your SAGIC in 2-Down wasn't saved: the word was locked.", input: 'SAGIC' });
  });

  it('words each reason', () => {
    const across = op({ kind: 'cells', writes: [{ col: 1, row: 0, value: 'A' }] });
    const reasons: Record<string, string> = {
      epoch: 'the puzzle was started over',
      phase: 'the puzzle moved to Create Hints',
      published: 'the puzzle was published',
      'not-found': 'this puzzle is no longer available',
    };
    for (const [code, reason] of Object.entries(reasons)) {
      expect(refusalNotice(across, code as never, serializeGrid(grid), 'grid').message).toBe(`Your MASKS in 1-Across wasn't saved: ${reason}.`);
    }
  });

  it('deletions keep nothing; hints and titles keep their text', () => {
    const clear = op({ kind: 'cells', writes: [{ col: 4, row: 1, value: null }] });
    expect(refusalNotice(clear, 'locked', serializeGrid(withLetter(grid, { col: 4, row: 1 }, null)), 'grid'))
      .toEqual({ message: "Your deletions in 2-Down weren't saved: the word was locked.", input: null });
    const hints = enterHintsPhase({ grid, hints: {}, phase: 'grid' });
    expect(refusalNotice(op({ kind: 'hint', key: '1-across', text: 'Disguises' }), 'published', serializeGrid(hints.grid), 'hints'))
      .toEqual({ message: "Your hint for 1-Across wasn't saved: the puzzle was published.", input: 'Disguises' });
    expect(refusalNotice(op({ kind: 'title', title: 'Monday' }), 'published', serializeGrid(grid), 'grid'))
      .toEqual({ message: "Your title wasn't saved: the puzzle was published.", input: 'Monday' });
  });

  it('structural operations say what didn’t happen', () => {
    const g = serializeGrid(grid);
    expect(refusalNotice(op({ kind: 'lock', word: { col: 0, row: 0, orientation: 'across', length: 5 } }), 'invalid', g, 'grid').message)
      .toBe("1-Across wasn't locked: it no longer fits the puzzle.");
    expect(refusalNotice(op({ kind: 'startOver', keepLockedWords: false }), 'published', g, 'grid').message)
      .toBe("Reset Grid wasn't saved: the puzzle was published.");
    expect(refusalNotice(op({ kind: 'enterHints' }), 'phase', g, 'grid').message)
      .toBe('The puzzle is already in Create Hints. Reload the page to see it.');
  });

  it('a stale publication is explained for the Publish dialog', () => {
    expect(publishRefusalMessage('stale')).toBe(
      "This puzzle changed after you checked it, so it wasn't published. Reload the page to see the changes, then publish again.",
    );
    expect(publishRefusalMessage('unsaved')).toMatch(/weren't saved/);
  });
});
